    {
      return false;
    }
    if (getNumberOfSeats() <= 0)
    {
      return false;
    }

    Trip trip = getTrip();
    if (trip.getNumberOfSeats() < getNumberOfSeats())
    {
      return false;
    }

    long bookingTime = getBookingDate().getTime();
    String departureTime = trip.getDepartureTime();
    if (departureTime == null)
    {
      return false;
    }

    try
    {
      long departureMillis = Long.parseLong(departureTime);
      long twoHoursMillis = 2L * 60L * 60L * 1000L;
      if (departureMillis - bookingTime <= twoHoursMillis)
      {
        return false;
      }
    }
    catch (NumberFormatException e)
    {
      return false;
    }

    for (Booking otherBooking : getCustomer().getBookings())
    {
      if (otherBooking != this && otherBooking.getBookingDate() != null && otherBooking.getTrip() != null)
      {
        Date otherDate = otherBooking.getBookingDate();
        if (bookingTime == otherDate.getTime() && otherBooking.getTrip().overlapsWith(trip))
        {
          return false;
        }
      }
    }

    updateTripSeats();
    return true;
    
